      const sF=sols(q0.ptsF,dF,q0.k2), sG=sols(q0.ptsG,dG,q0.k2);
      if(sF.length!==2) vus.push('f(x) = '+q0.k2+' a '+sF.length+' solution(s) au lieu de 2');
