    const inp=$("pyn-in"); inp.value="print("+A+"je m"+A+"appelle"+A+", nom)"; pynModifieeC();
    pynExecuterC(); $("pynEntree").value="Léa"; $("pynEntree").dispatchEvent(new KeyboardEvent("keydown",{key:"Enter"}));
    checkPYN();
