      qs.forEach(function(q){ vues[pfrVar(q)]=1; if(q.etape!=="a"||q.r.join("")!==""||q.ok!==null) vus.push("question non vierge"); if(q.n<3||q.n>9) vus.push("n = "+q.n); });
