    if(document.getElementById("pof-prog").value!==pofModele({e:"a"})+NL+pofModele({e:"b"})) vus.push("le c) ne s’ouvre pas sur le a) (juste) puis le b) (corrigé) : "+JSON.stringify(document.getElementById("pof-prog").value));
