    const mod=document.querySelector("#pfnModele .sol");
    if(!mod||mod.textContent!==pfnModele(test.questions[0])) vus.push("pas de modèle vert sous la copie fausse");
    nextPFN(); ta=document.getElementById("pfn-prog");
