    ["A","B"].forEach(function(c){ ["ptm-prog"+c,"ptmRun"+c,"ptmConsole"+c].forEach(function(id){ const et=c==="A"?A:B; if(!et||!et.querySelector("#"+id)) vus.push(id+" hors du cadre de sa partie"); }); });
