    const D1=pduDuree(test.questions[1]), t1=net(document.getElementById("pduEtape").textContent);
    if(t1.indexOf("si on rentre "+D1+" min")<0||t1.indexOf(D1+" // 60")<0) vus.push("la question 2 ne suit pas sa durée : "+t1);
